use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::{Path,PathBuf},process::Command};const R:&str="/home/ubuntu/src/zopro-perf-work/sdk-link-flags176";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-31-sdk-link-flags176";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn walk(p:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){walk(&p,out)}else{out.push(p)}}}
fn main(){let base=Path::new(R).join("archive-review");assert!(!base.exists());fs::create_dir(&base).unwrap();let mut counts=BTreeMap::new();for name in["workflow","receipts","codegen"]{let out=base.join(name);fs::create_dir(&out).unwrap();assert!(Command::new("tar").arg("-xzf").arg(Path::new(D).join(format!("artifacts/{name}.tar.gz"))).arg("-C").arg(&out).status().unwrap().success());let mut files=vec![];walk(&out,&mut files);let n=files.len();for p in files{let rel=p.strip_prefix(&out).unwrap();assert_eq!(hash(&p),hash(Path::new(R).join(rel)));let s=rel.to_string_lossy();for suffix in["-sdk",".data",".rlib",".a1q",".b2q"]{assert!(!s.ends_with(suffix))}}counts.insert(name,n);}
 let notes:Value=serde_json::from_slice(&fs::read(Path::new(D).join("artifacts/report-corrections.json")).unwrap()).unwrap();for v in notes.as_array().unwrap(){let path=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks").join(v["report"].as_str().unwrap()).join("README.md");assert_eq!(hash(path),v["after_README_sha256"]);}
 let text=fs::read_to_string(Path::new(D).join("README.md")).unwrap();let mut links=0;for x in text.split("](").skip(1){let t=x.split(')').next().unwrap();if t!="SHA256SUMS"&&!t.starts_with("http"){assert!(Path::new(D).join(t).is_file())}links+=1;}
 let v=json!({"passed":true,"archive_file_counts_byte_exact":counts,"README_links":links,"two_previous_report_notes_match":true,"acceptedSDK_byte_identical":true,"raw442commands_independently_reviewed":true,"new_proofs":0,"backend_adopted":false,"private_inputs_binaries_libraries_raw_perf_not_published":true});fs::write(Path::new(D).join("artifacts/publication-review.json"),serde_json::to_vec_pretty(&v).unwrap()).unwrap();println!("{v}");}
